TLM.f("Tempora/Adv4-5",{"officium":"Feria VI infra Hebdomadam IV Adventus","rule":["Oratio Dominica","no Gloria","no Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"ruleInherited":["no Gloria","Credo","Suffr=Maria1;Ecclesiæ,Papa;;"],"fallback":"Tempora/Adv4-0","from":{"Introitus":"Tempora/Adv4-0","Oratio":"Tempora/Adv4-0","Lectio":"Tempora/Adv4-0","Graduale":"Tempora/Adv4-0","GradualeF":"Tempora/Adv4-0","Evangelium":"Tempora/Adv4-0","Offertorium":"Tempora/Adv4-0","Secreta":"Tempora/Adv4-0","Communio":"Tempora/Adv4-0","Postcommunio":"Tempora/Adv4-0"},"sections":{"Introitus":[{"k":"ref","la":"Isa 45:8"},{"k":"text","la":"Roráte, cœli, désuper, et nubes pluant justum: aperiátur terra, et gérminet Salvatórem"},{"k":"ref","la":"Ps 18:2"},{"k":"text","la":"Cœli enárrant glóriam Dei: et ópera mánuum ejus annúntiat firmaméntum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Roráte, cœli, désuper, et nubes pluant justum: aperiátur terra, et gérminet Salvatórem"}],"Oratio":[{"k":"text","la":"Excita, quǽsumus, Dómine, poténtiam tuam, et veni: et magna nobis virtúte succúrre; ut per auxílium grátiæ tuæ, quod nostra peccáta præpédiunt, indulgéntia tuæ propitiatiónis accéleret:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 4:1-5"},{"k":"text","la":"Fratres: Sic nos exístimet homo ut minístros Christi, et dispensatóres mysteriórum Dei. Hic jam quǽritur inter dispensatóres, ut fidélis quis inveniátur. Mihi autem pro mínimo est, ut a vobis júdicer aut ab humano die: sed neque meípsum judico. Nihil enim mihi cónscius sum: sed non in hoc justificátus sum: qui autem júdicat me, Dóminus est. Itaque nolíte ante tempus judicáre, quoadúsque véniat Dóminus: qui et illuminábit abscóndita tenebrárum, et manifestábit consília córdium: et tunc laus erit unicuique a Deo."}],"Graduale":[{"k":"ref","la":"Ps 144:18; 144:21"},{"k":"text","la":"Prope est Dóminus ómnibus invocántibus eum: ómnibus, qui ínvocant eum in veritáte."},{"k":"text","la":"Laudem Dómini loquétur os meum: et benedícat omnis caro nomen sanctum ejus. Allelúja, allelúja,","mark":"V"},{"k":"text","la":"Veni, Dómine, et noli tardáre: reláxa facínora plebis tuæ Israël. Allelúja.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 144:18; 144:21"},{"k":"text","la":"Prope est Dóminus ómnibus invocántibus eum: ómnibus, qui ínvocant eum in veritáte."},{"k":"text","la":"Laudem Dómini loquétur os meum: et benedícat omnis caro nomen sanctum ejus.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secundum Lucam"},{"k":"ref","la":"Luc 3:1-6"},{"k":"text","la":"Anno quintodécimo impérii Tibérii Cǽsaris, procuránte Póntio Piláto Judǽam, tetrárcha autem Galilǽæ Heróde, Philíppo autem fratre ejus tetrárcha Iturǽæ et Trachonítidis regionis, et Lysánia Abilínæ tetrárcha, sub princípibus sacerdotum Anna et Cáipha: factum est verbum Domini super Joannem, Zacharíæ filium, in deserto. Et venit in omnem regiónem Jordánis, prǽdicans baptísmum pæniténtiæ in remissiónem peccatórum, sicut scriptum est in libro sermónum Isaíæ Prophétæ: Vox clamántis in desérto: Paráte viam Dómini: rectas fácite sémitas ejus: omnis vallis implébitur: et omnis mons et collis humiliábitur: et erunt prava in dirécta, et áspera in vias planas: et vidébit omnis caro salutáre Dei."}],"Offertorium":[{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, gratia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui."}],"Secreta":[{"k":"text","la":"Sacrifíciis præséntibus, quǽsumus, Dómine, placátus inténde: ut et devotióni nostræ profíciant et salúti."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Is 7:14"},{"k":"text","la":"Ecce, Virgo concípiet et páriet fílium: et vocábitur nomen ejus Emmánuel."}],"Postcommunio":[{"k":"text","la":"Sumptis munéribus, quǽsumus, Dómine: ut, cum frequentatióne mystérii, crescat nostræ salútis efféctus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f5880ffb7ba7465a":{"t":"Iz, 45, 8, Ps 18, 2\n(Iz 45, 8) Rosite, nebesa, s visine! Oblaci, daždite Pravednika! Neka se otvori zemlja i neka iz nje nikne Spasitelj! (Ps 18, 2) Nebesa pripovijedaju slavu Božju i nebeski svod navješćuje djelo njegovih ruku.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 45, 8) Rosite, nebesa, s visine! Oblaci, daždite Pravednika! Neka se otvori zemlja i neka iz nje nikne Spasitelj!","v":"isai → ∅; isai → ∅","kn":"(Izai. 45, 8). Rosite, nebesa, s visine i oblaci neka dažde Pravednika! Neka se otvori zemlja i neka iz nje nikne Spasitelj! (Ps. 18, 2). Nebesa pričaju slavu Božju i djela ruku njegovih naviješta svod nebeski. Slava Ocu . . . Rosite . . .","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"ee51f26ff1c1a48e":{"t":"<i>Pomolimo se</i>.\nPokreni, molimo, Gospodine, svoju silu i dođi, i s velikom nam jakošću priteci u pomoć, da po tvojoj milosti ono što naši grijesi sprečavaju pospješi blagost tvoga milosrđa:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Probudi, molimo, Gospodine svoju moć i dođi i velikom nam moći priteci, da pomoću Tvoje milosti oproštenje Tvoga smilovanja pospješi spasenje, koje priječe naši grijesi; ko-ji živiš i kra- Ijuješ ...","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"1b9db85ac76f4893":{"t":"1 Kor 4, 1-5\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: neka nas svatko smatra Kristovim slugama i upraviteljima Božjih tajna. Od upravitelja se traži da bude vjeran. Meni je vrlo malo do toga kako me vi sudite ili drugi ljudi. A ni sam sebe ne sudim. Nisam ničega svjestan, ali zato još nisam opravdan. Moj je sudac Gospodin. – Zato nemojte suditi prije vremena, dok ne dođe Gospodin. On će osvijetliti što je sakriveno u tami i otkriti nakane srdaca, i tada će svatko primiti zasluženu hvalu od Boga.","kn":"Čitanje poslanice bi. Pavla Korinćanina (I, 4, 1-5). Braćo! Svaki neka nas teko drži kao Kristove sluge i djelitelje Božjih tajna. Od djelitelja se traži, da bude vjeran. Meni je vrlo malo do toga, što me sudite vi Ui ljudi, a ja ne sudim ni sama sebe, a savjest mi ništa ne predbacuje. Ali tim ja još nijesam opravdan; Gospodin je onaj, koji me sudi. Zato nemojte suditi prije vremena, dok ne dođe Gospodin, koji će i rasvijetliti, što je sakriveno u tami, i , objaviti nakane srdaca, i tada će svaki primiti pohvalu od Boga.","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"5fcd31d3abd4fd13":{"t":"Ps 144, 18 i 21\nGospodin je blizu svima koji ga zazivaju, svima koji ga zazivaju iskreno. Neka moja usta navješćuju hvalu Gospodnju i svaki čovjek neka blagoslivlja sveto ime njegovo.","kn":"(Ps. 144, 18, 21). Blizu je Gospodin svima, koji ga zazivaju, koji ga zazivaju u Istini. Usta će moja zboriti hvalu Božju i svaki čovjek neka blagosiva njegovo sveto ime.","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"57ff9609fb7c344a":{"t":"Lk 3, 1-6\nSlijedi sveto Evanđelje po Luki. Petnaeste godine vladanja cara Tiberija, kad je Poncije Pilat bio upravitelj Judeje, Herod četverovlasnik Galileje, njegov brat Filip četverovlasnik Itureje i Trahonitide, a Lizanija četverovlasnik Abilene, za velikih svećenika Ane i Kaife, dođe riječ Gospodnja Ivanu, sinu Zakarijinu, u pustinji. I on obiđe sav kraj oko Jordana propovijedajući krštenje pokore na oproštenje grijeha. Kao što je pisano u knjizi proroka Izaije: Glas onoga koji viče u pustinji: Pripravite put Gospodinu, poravnite staze njegove. Neka se svaka dolina ispuni, a svaka gora i brijeg neka se slegne. Neka krivudavi putovi postanu pravi, a neravni neka postanu ravni. I svi će ljudi vidjeti spasenje Božje.","kn":"t Slijedi sveto Evanđelje po Luki (3, 1-6). Gospodin pozva Ivana, sina Zaharijina, u pustinji petna- este godine vladanja cara Tiberija, kad je Poncije Pilat bio upravitelj Judeje i Herod četverovlasnik Galileje, a njegov brat Filip četverovlasnik Itureje i Trahonitide i Lisanije četverovlasnik Abilene, za velikih svećenika Ane i Kaife. I on je prolazio svom okolinom Jordana i propovijiedao je krst pokore za oprost grijeha, kao što je pisano u knjizi govora proroka Izaije: Glas onoga, koji viče u pu. stinji: Pripravite put Gospodnji, poravnajte njegove staze. Svaka dolina neka se ispuni, i neka se slegne svaka gora i brijeg. Neka se iis|pravi što je krivo, i hrapavi putevi neka postanu glatki. I svi će ljudi vidjeti spas Božji.i","knRef":"Kniewald 1942, str. 52–53 (snimka 27) (OCR)"},"9f99f01cc37689c1":{"t":"Lk 1, 28 i 42\nZdravo, Marijo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje.","kn":"(Lk. 1, 28). Zdravo Marijo, milosti puna, Gospodin s Tobom, blagoslovena Ti među ženama, blagosloven plod utrobe Tvoje.","knRef":"Kniewald 1942, str. 38–39 (snimka 20) (OCR)"},"39484622e18d8d21":{"t":"Pogledaj, molimo, Gospodine, umilostivljen na ove žrtvene darove, da budu na korist našoj pobožnosti i spasenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, molimo Te, milostivo na ove žrtve i podaj, da koriste i našoj pobožnosti i spasenju, po G. n.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"11efe5bb9752667a":{"t":"Iz 7, 14\nEvo, Djevica će začeti i roditi Sina, i on će se zvati Emanuel.","kn":"(Izal. 7, 14). Evo, Djevica će začeti i rodit će Sina i zvat će se ime njegovo Emanuel.","knRef":"Kniewald 1942, str. 534–535 (snimka 268) (OCR)"},"5f2ccb010a1af01c":{"t":"<i>Pomolimo se</i>.\nPrimivši darove molimo, Gospodine, da čestim sudjelovanjem u ovom otajstvu raste djelo našega spasenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Blagovavši časne darove, molimo. Gospodine, da čestim izvršivanjem otajstva poraste učinak našega spasenja, po G. n.","knRef":"Kniewald 1942, str. 370–371 (snimka 186) (OCR)"}}});
